create extension if not exists pgcrypto;
create type public.user_role as enum ('ADMIN','MANAGER','STAFF');
create type public.order_status as enum ('PENDING','CONFIRMED','PREPARING','READY','COMPLETED','CANCELLED');
create table public.users (id uuid primary key default gen_random_uuid(), name text not null, email text unique not null, password_hash text not null, role public.user_role not null default 'STAFF', active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.categories (id uuid primary key default gen_random_uuid(), name text unique not null, description text, display_order integer not null default 0, active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.products (id uuid primary key default gen_random_uuid(), name text not null, description text, price numeric(10,2) not null check (price >= 0), available boolean not null default true, category_id uuid not null references public.categories(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.orders (id uuid primary key default gen_random_uuid(), number text unique not null, lines jsonb not null, total numeric(10,2) not null check (total >= 0), status public.order_status not null default 'PENDING', created_by uuid references public.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index products_category_idx on public.products(category_id); create index orders_status_idx on public.orders(status); create index orders_created_at_idx on public.orders(created_at desc);
alter table public.users enable row level security; alter table public.categories enable row level security; alter table public.products enable row level security; alter table public.orders enable row level security;
